import re
import math
import numpy as np
from typing import List, Dict, Any, Tuple, Set

# ------------------------------------------------------------------
# Helper utilities (can be reused from the sandbox)
# ------------------------------------------------------------------
def node_by_title(doc: Any, title: str):
    return next((n for n in doc["nodes"] if n.get("title") == title), None)

def children(doc: Any, node):
    if not node:
        return []
    raw_ids = node.get("children", [])
    return [next((n for n in doc["nodes"] if n["node_id"] == cid), None) for cid in raw_ids]

def scope_nodes(doc: Any, scope):
    return children(doc, node_by_title(doc, scope))

# ------------------------------------------------------------------
# Parsing utilities
# ------------------------------------------------------------------
def get_motion_rows(doc: Any, scope: str, obj_id: str) -> List[Dict[str, Any]]:
    """Return motion log rows for a given object in a scope."""
    rows = []
    for child in scope_nodes(doc, scope):
        if child["kind"] == "table" and child["title"].startswith(f"{scope}: Motion log"):
            for r in child.get("table", {}).get("rows", []):
                if not r or len(r) < 7:
                    continue
                obj_str = r[1]
                m = re.match(r"(\d+)\s+", obj_str)
                if not m:
                    continue
                oid = m.group(1)
                if oid == obj_id:
                    try:
                        rows.append({
                            "frame": int(r[0]),
                            "pos": np.array([float(r[2]), float(r[3])]),
                            "vel": np.array([float(r[4]), float(r[5])]),
                            "speed": float(r[6]),
                        })
                    except ValueError:
                        pass
    rows.sort(key=lambda r: r["frame"])
    return rows

# ------------------------------------------------------------------
# Global constant estimation (several helper functions)
# ------------------------------------------------------------------
def compute_global_radii(doc: Any) -> Dict[str, float]:
    """Estimate object radii from recorded inter‑collision distances."""
    pair_distances: List[Tuple[int, int, float]] = []
    for scope in [n["title"] for n in doc["nodes"] if n["kind"] == "text" and n["title"].startswith("Video ")]:
        for child in scope_nodes(doc, scope):
            if child["kind"] == "list" and child["title"].startswith(f"{scope}: Events"):
                for line in child.get("lines", []):
                    ids = [m.group(1) for m in re.finditer(r"Object\s+(\d+)", line)]
                    if len(ids) < 2:
                        continue
                    m_frame = re.match(r"Frame\s+(\d+):", line)
                    if not m_frame:
                        continue
                    frame = int(m_frame.group(1))
                    # gather positions of objects at this frame
                    pos = {}
                    for col in scope_nodes(doc, scope):
                        if col["kind"] == "table" and col["title"].startswith(f"{scope}: Motion log"):
                            for r in col.get("table", {}).get("rows", []):
                                if not r or len(r) < 7:
                                    continue
                                obj_str = r[1]
                                m = re.match(r"(\d+)\s+", obj_str)
                                if not m:
                                    continue
                                oid = m.group(1)
                                if oid in ids and int(r[0]) == frame:
                                    try:
                                        pos[oid] = np.array([float(r[2]), float(r[3])])
                                    except ValueError:
                                        pass
                    if len(pos) == len(ids):
                        for i in range(len(ids)):
                            for j in range(i+1, len(ids)):
                                d = np.linalg.norm(pos[ids[i]] - pos[ids[j]])
                                pair_distances.append((int(ids[i]), int(ids[j]), d))
    if not pair_distances:
        return {}
    # Build linear system A r = b where r_i + r_j = d_ij
    ids = sorted({i for i, _, _ in pair_distances} | {j for _, j, _ in pair_distances})
    idx = {oid: i for i, oid in enumerate(ids)}
    m = len(pair_distances)
    n = len(ids)
    A = np.zeros((m, n))
    b = np.zeros(m)
    for k, (i, j, d) in enumerate(pair_distances):
        A[k, idx[i]] = 1
        A[k, idx[j]] = 1
        b[k] = d
    # Least‑squares solve; enforce non‑negative radii with truncation
    sol, *_ = np.linalg.lstsq(A, b, rcond=None)
    radii = {str(oid): max(sol[idx[oid]], 0.01) for oid in ids}
    return radii

def compute_global_friction(doc: Any) -> float:
    """Estimate a constant speed drop per frame from all motion logs."""
    drops = []
    for scope in [n["title"] for n in doc["nodes"] if n["kind"] == "text" and n["title"].startswith("Video ")]:
        for child in scope_nodes(doc, scope):
            if child["kind"] == "table" and child["title"].startswith(f"{scope}: Motion log"):
                rows_by_obj: Dict[str, List[Tuple[int, float]]] = {}
                for r in child.get("table", {}).get("rows", []):
                    if not r or len(r) < 7:
                        continue
                    obj_str = r[1]
                    m = re.match(r"(\d+)\s+", obj_str)
                    if not m:
                        continue
                    oid = m.group(1)
                    try:
                        speed = float(r[6])
                    except ValueError:
                        continue
                    rows_by_obj.setdefault(oid, []).append((int(r[0]), speed))
                for oid, lst in rows_by_obj.items():
                    lst.sort(key=lambda x: x[0])
                    for i in range(1, len(lst)):
                        delta = lst[i-1][1] - lst[i][1]
                        if delta > 0:
                            drops.append(delta)
    if not drops:
        return 0.0
    return float(np.median(drops))

# Pre‑compute global constants once
OBJ_RADII = compute_global_radii(doc)
GLOBAL_FRIC = compute_global_friction(doc)

# ------------------------------------------------------------------
# Main simulation routine
# ------------------------------------------------------------------
def simulate(doc, scope, removed=(), horizon=None, start=0.0):
    """
    Forward model of the interactions in `scope`.
    The model does not look ahead beyond `start` on the recorded data.
    """
    # Resolve horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
    horizon = float(horizon)
    start = float(start)

    # Gather entities in the scope
    ents = entities(doc, scope)
    ent_ids = {e["id"] for e in ents}
    ent_ids.difference_update(removed)

    # Prepare per‑object motion records mapping frame -> state
    obj_state_map: Dict[str, Dict[int, Dict[str, np.ndarray]]] = {}
    first_frames: Dict[str, int] = {}
    for oid in ent_ids:
        rows = get_motion_rows(doc, scope, oid)
        if not rows:
            continue
        # Build frame -> (pos, vel, speed)
        frame_map = {r["frame"]: r for r in rows}
        obj_state_map[oid] = frame_map
        first_frames[oid] = rows[0]["frame"]

    # Simulation loop over integer frames
    events: List[Dict[str, Any]] = []
    # Convert start to integer frame index (floor)
    start_frame = int(math.floor(start))
    horizon_frame = int(math.ceil(horizon))

    # Keep current state dict for each object
    curr_state: Dict[str, Dict[str, Any]] = {}

    for t in range(start_frame, horizon_frame):
        # 1. Update presence and state from motion logs
        for oid in ent_ids:
            fm = obj_state_map.get(oid, {})
            present = t in fm
            if present:
                rec = fm[t]
                curr_state[oid] = {
                    "pos": rec["pos"].copy(),
                    "vel": rec["vel"].copy(),
                    "first_frame": first_frames[oid],
                }
            else:
                # If object hasn't appeared yet, skip
                if t < first_frames.get(oid, float("inf")):
                    continue
                # If object exists but no record at this frame, we keep the last known state
                if oid in curr_state:
                    # update position by last known velocity
                    pass

        # 2. Apply friction (constant speed drop)
        for oid, st in curr_state.items():
            v = st["vel"]
            speed = np.linalg.norm(v)
            if speed > 0:
                new_speed = max(speed - GLOBAL_FRIC, 0.0)
                if new_speed < speed:
                    st["vel"] = v * (new_speed / speed)

        # 3. Move objects
        for oid, st in curr_state.items():
            st["pos"] += st["vel"]

        # 4. Detect collisions
        ids_list = list(curr_state.keys())
        for i in range(len(ids_list)):
            for j in range(i + 1, len(ids_list)):
                oid1, oid2 = ids_list[i], ids_list[j]
                st1, st2 = curr_state[oid1], curr_state[oid2]
                d = np.linalg.norm(st1["pos"] - st2["pos"])
                r_sum = OBJ_RADII.get(oid1, 0.5) + OBJ_RADII.get(oid2, 0.5)
                if d <= r_sum + 1e-6:
                    ev_time = float(t + 1)  # collision occurs after movement step
                    if ev_time >= start:
                        events.append({
                            "time": ev_time,
                            "kind": "collision",
                            "participants": sorted([oid1, oid2], key=lambda x: int(x))
                        })
                    # Elastic collision response (equal masses)
                    n = st2["pos"] - st1["pos"]
                    if np.linalg.norm(n) == 0:
                        continue
                    n = n / np.linalg.norm(n)
                    v1, v2 = st1["vel"], st2["vel"]
                    rel = v1 - v2
                    v_rel_n = np.dot(rel, n)
                    if v_rel_n > 0:
                        # already separating
                        continue
                    impulse = -2 * v_rel_n
                    st1["vel"] = v1 + impulse * n
                    st2["vel"] = v2 - impulse * n

    # Cleanup: sort events chronologically
    events.sort(key=lambda e: e["time"])
    return events

