# ------------------------------------------------------------------
# Global caches for per‑document constants
# ------------------------------------------------------------------
_RADI_CACHE: Dict[int, Dict[str, float]] = {}
_FRIC_CACHE: Dict[int, float] = {}

def _compute_global_radii(doc: Any) -> Dict[str, float]:
    """Estimate radii from all recorded collision distances."""
    pair_distances: List[Tuple[int, int, float]] = []
    for scope in [n["title"] for n in doc["nodes"] if n["kind"] == "text" and n["title"].startswith("Video ")]:
        for child in scope_nodes(doc, scope):
            if child["kind"] == "list" and child["title"].startswith(f"{scope}: Events"):
                for line in child.get("lines", []):
                    ids = [m.group(1) for m in re.finditer(r"Object\s+(\d+)", line)]
                    if len(ids) < 2:
                        continue
                    m_frame = re.match(r"Frame\s+(\d+):", line)
                    if not m_frame:
                        continue
                    frame = int(m_frame.group(1))
                    pos = {}
                    for log in scope_nodes(doc, scope):
                        if log["kind"] == "table" and log["title"].startswith(f"{scope}: Motion log"):
                            for r in log.get("table", {}).get("rows", []):
                                if not r or len(r) < 7:
                                    continue
                                obj_str = r[1]
                                m = re.match(r"(\d+)\s+", obj_str)
                                if not m:
                                    continue
                                oid = m.group(1)
                                if oid in ids and int(r[0]) == frame:
                                    try:
                                        pos[oid] = np.array([float(r[2]), float(r[3])])
                                    except ValueError:
                                        pass
                    if len(pos) == len(ids):
                        for i in range(len(ids)):
                            for j in range(i + 1, len(ids)):
                                pair_distances.append((int(ids[i]), int(ids[j]), np.linalg.norm(pos[ids[i]] - pos[ids[j]])))

    if not pair_distances:
        return {}
    ids = sorted({i for i, _, _ in pair_distances} | {j for _, j, _ in pair_distances})
    idx = {oid: i for i, oid in enumerate(ids)}
    m = len(pair_distances)
    n = len(ids)
    A = np.zeros((m, n))
    b = np.zeros(m)
    for k, (i, j, d) in enumerate(pair_distances):
        A[k, idx[i]] = 1
        A[k, idx[j]] = 1
        b[k] = d
    sol, *_ = np.linalg.lstsq(A, b, rcond=None)
    return {str(oid): max(float(sol[idx[oid]]), 0.01) for oid in ids}

def _compute_global_friction(doc: Any) -> float:
    """Median positive speed drop per frame across all motion logs."""
    drops = []
    for scope in [n["title"] for n in doc["nodes"] if n["kind"] == "text" and n["title"].startswith("Video ")]:
        for child in scope_nodes(doc, scope):
            if child["kind"] == "table" and child["title"].startswith(f"{scope}: Motion log"):
                rows_by_obj: Dict[str, List[Tuple[int, float]]] = {}
                for r in child.get("table", {}).get("rows", []):
                    if not r or len(r) < 7:
                        continue
                    obj_str = r[1]
                    m = re.match(r"(\d+)\s+", obj_str)
                    if not m:
                        continue
                    oid = m.group(1)
                    try:
                        speed = float(r[6])
                    except ValueError:
                        continue
                    rows_by_obj.setdefault(oid, []).append((int(r[0]), speed))
                for lst in rows_by_obj.values():
                    lst.sort(key=lambda x: x[0])
                    for i in range(1, len(lst)):
                        delta = lst[i-1][1] - lst[i][1]
                        if delta > 0:
                            drops.append(delta)
    return float(np.median(drops)) if drops else 0.0

def _get_global_constants(doc: Any) -> Tuple[Dict[str, float], float]:
    key = id(doc)
    if key not in _RADI_CACHE:
        _RADI_CACHE[key] = _compute_global_radii(doc)
    if key not in _FRIC_CACHE:
        _FRIC_CACHE[key] = _compute_global_friction(doc)
    return _RADI_CACHE[key], _FRIC_CACHE[key]

# ------------------------------------------------------------------
# Motion log extraction helper
# ------------------------------------------------------------------
def _motion_records(doc: Any, scope: str, oid: str) -> List[Dict[str, Any]]:
    """Return all rows (frame, pos, vel) for the given object."""
    rows = []
    for child in scope_nodes(doc, scope):
        if child["kind"] == "table" and child["title"].startswith(f"{scope}: Motion log"):
            for r in child.get("table", {}).get("rows", []):
                if not r or len(r) < 7:
                    continue
                obj_str = r[1]
                m = re.match(r"(\d+)\s+", obj_str)
                if not m:
                    continue
                oid_row = m.group(1)
                if oid_row != oid:
                    continue
                try:
                    rows.append({
                        "frame": int(r[0]),
                        "pos": np.array([float(r[2]), float(r[3])]),
                        "vel": np.array([float(r[4]), float(r[5])]),
                    })
                except ValueError:
                    continue
    rows.sort(key=lambda r: r["frame"])
    return rows

# ------------------------------------------------------------------
# Main simulation
# ------------------------------------------------------------------
def simulate(doc: Any, scope: str, removed=(), horizon=None, start=0.0) -> List[Dict[str, Any]]:
    """
    Forward model for a video scope.
    Returns interaction events after `start` up to `horizon` (frames as time units).
    """
    if horizon is None:
        horizon = recorded_end(doc, scope)
    start = float(start)
    horizon = float(horizon)
    start_frame = int(math.floor(start))
    horizon_frame = int(math.ceil(horizon))

    # Get global constants for this document
    radii, fric = _get_global_constants(doc)

    # Collect entities
    all_entities = entities(doc, scope)
    all_ids = {e["id"] for e in all_entities}
    removed_set = set(map(str, removed))
    object_ids = all_ids - removed_set

    # For each object, determine relevant recorded frames
    init_state: Dict[str, Dict[str, Any]] = {}
    entry_frame: Dict[str, int] = {}
    for oid in object_ids:
        rows = _motion_records(doc, scope, oid)
        if not rows:
            continue
        # Latest frame <= start
        last_before = None
        first_after = None
        for r in rows:
            if r["frame"] <= start_frame:
                last_before = r
            elif r["frame"] > start_frame and first_after is None:
                first_after = r
        if last_before:
            init_state[oid] = {
                "pos": last_before["pos"].copy(),
                "vel": last_before["vel"].copy(),
                "first_frame": last_before["frame"],
                "present": True,
            }
            # Advance this initial state to the exact start time
            steps = start_frame - last_before["frame"]
            for _ in range(steps):
                # friction
                speed = np.linalg.norm(init_state[oid]["vel"])
                if speed > 0:
                    new_speed = max(speed - fric, 0.0)
                    init_state[oid]["vel"] *= new_speed / speed if speed > 0 else 0
                init_state[oid]["pos"] += init_state[oid]["vel"]
        elif first_after:
            # Will appear at its first recorded frame
            init_state[oid] = {
                "present": False,
                "pos": first_after["pos"].copy(),
                "vel": first_after["vel"].copy(),
                "first_frame": first_after["frame"],
            }
            entry_frame[oid] = first_after["frame"]
        else:
            # No records at all
            continue

    # Simulation state dictionary
    state: Dict[str, Dict[str, Any]] = {}
    for oid, s in init_state.items():
        state[oid] = s.copy()

    events: List[Dict[str, Any]] = []

    # Main time loop
    for t in range(start_frame, horizon_frame):
        # 1. Handle objects that newly appear at this frame
        for oid, s in state.items():
            if not s["present"]:
                if t >= s["first_frame"]:
                    # Activate with record state
                    s["present"] = True
                    s["pos"] = s["pos"].copy()
                    s["vel"] = s["vel"].copy()
        # 2. Apply friction and move all present objects
        for s in state.values():
            if not s["present"]:
                continue
            v = s["vel"]
            speed = np.linalg.norm(v)
            if speed > 0:
                new_speed = max(speed - fric, 0.0)
                s["vel"] = v * (new_speed / speed) if speed > 0 else v
            s["pos"] += s["vel"]

        # 3. Detect collisions (after movement)
        ids = [oid for oid, s in state.items() if s["present"]]
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                oid1, oid2 = ids[i], ids[j]
                s1, s2 = state[oid1], state[oid2]
                d = np.linalg.norm(s1["pos"] - s2["pos"])
                r_sum = radii.get(oid1, 0.5) + radii.get(oid2, 0.5)
                if d <= r_sum + 1e-8:
                    ev_time = float(t + 1)  # after the movement step
                    if ev_time >= start:
                        events.append({
                            "time": ev_time,
                            "kind": "collision",
                            "participants": sorted([oid1, oid2], key=lambda x: int(x))
                        })
                    # Elastic collision (equal mass)
                    n_vec = s2["pos"] - s1["pos"]
                    if np.linalg.norm(n_vec) == 0:
                        continue
                    n = n_vec / np.linalg.norm(n_vec)
                    v_rel = s1["vel"] - s2["vel"]
                    v_rel_n = np.dot(v_rel, n)
                    if v_rel_n > 0:
                        continue
                    impulse = -2 * v_rel_n
                    s1["vel"] = s1["vel"] + impulse * n
                    s2["vel"] = s2["vel"] - impulse * n

    # Sort events chronologically
    events.sort(key=lambda e: e["time"])
    return events

